## 1.3 Implementation — Singly Linked List

```csharp
public class SinglyLinkedList<T>
{
    private class Node
    {
        public T Value;
        public Node? Next;
        public Node(T value) => Value = value;
    }

    private Node? _head;
    private int _count;

    public int Count => _count;

    // O(1)
    public void AddFirst(T value)
    {
        var newNode = new Node(value) { Next = _head };
        _head = newNode;
        _count++;
    }

    // O(n) — could be O(1) with tail pointer
    public void AddLast(T value)
    {
        var newNode = new Node(value);

        if (_head is null)
        {
            _head = newNode;
        }
        else
        {
            var current = _head;
            while (current.Next is not null)
                current = current.Next;
            current.Next = newNode;
        }

        _count++;
    }

    // O(1)
    public T RemoveFirst()
    {
        if (_head is null) throw new InvalidOperationException("List is empty");

        T value = _head.Value;
        _head = _head.Next;
        _count--;
        return value;
    }

    // O(n)
    public bool Contains(T value)
    {
        var current = _head;
        while (current is not null)
        {
            if (EqualityComparer<T>.Default.Equals(current.Value, value))
                return true;
            current = current.Next;
        }
        return false;
    }

    // O(n) — Reverse in-place
    public void Reverse()
    {
        Node? prev = null;
        var current = _head;

        while (current is not null)
        {
            var next = current.Next;   // Save
            current.Next = prev;       // Reverse pointer
            prev = current;            // Advance prev
            current = next;            // Advance current
        }

        _head = prev;
    }
}
```

## 1.4 Critical Interview Patterns

### Floyd's Cycle Detection (Tortoise & Hare)

```csharp
/// <summary>
/// Detects if a linked list has a cycle.
/// Time: O(n) | Space: O(1)
/// </summary>
public class ListNode
{
    public int Val;
    public ListNode? Next;
    public ListNode(int val) => Val = val;
}

public static bool HasCycle(ListNode? head)
{
    var slow = head;
    var fast = head;

    while (fast?.Next is not null)
    {
        slow = slow!.Next;
        fast = fast.Next.Next;

        if (slow == fast) return true; // They meet → cycle exists
    }

    return false;
}

/// <summary>
/// Finds the START of the cycle.
/// After detection, reset one pointer to head. 
/// Move both at speed 1 — they meet at cycle start.
/// Mathematical proof: distance from head to cycle start = 
///                     distance from meeting point to cycle start
/// </summary>
public static ListNode? FindCycleStart(ListNode? head)
{
    var slow = head;
    var fast = head;

    // Phase 1: Detect cycle
    while (fast?.Next is not null)
    {
        slow = slow!.Next;
        fast = fast.Next.Next;
        if (slow == fast) break;
    }

    if (fast?.Next is null) return null; // No cycle

    // Phase 2: Find start
    slow = head;
    while (slow != fast)
    {
        slow = slow!.Next;
        fast = fast!.Next;
    }

    return slow;
}
```

### Merge Two Sorted Lists

```csharp
/// <summary>
/// Merges two sorted linked lists into one sorted list.
/// Time: O(n + m) | Space: O(1) — reuses existing nodes
/// </summary>
public static ListNode? MergeSorted(ListNode? l1, ListNode? l2)
{
    var dummy = new ListNode(0);
    var current = dummy;

    while (l1 is not null && l2 is not null)
    {
        if (l1.Val <= l2.Val)
        {
            current.Next = l1;
            l1 = l1.Next;
        }
        else
        {
            current.Next = l2;
            l2 = l2.Next;
        }
        current = current.Next;
    }

    current.Next = l1 ?? l2; // Attach remaining

    return dummy.Next;
}
```

