dp[2]: j=0, "le" no. j=1, dp[1]=false. dp[2]=false
dp[3]: j=0, "lee" no. ... dp[3]=false
dp[4]: j=0, dp[0]=true, s[0..3]="leet" → YES! dp[4]=true
dp[5]: j=0 "leetc" no, j=4 dp[4]=true "c" no. dp[5]=false
