### Subsets via Bitmask (Bridge to Bitmask DP)

**Key concept:** A bitmask of length n can represent any subset of n elements. Bit `i` being 1 means element `i` is in the subset.

```typescript
// Generate all subsets using bitmasks
function subsetsViaBitmask(nums: number[]): number[][] {
    const n = nums.length;
    const result: number[][] = [];

    // There are 2^n possible subsets
    for (let mask = 0; mask < (1 << n); mask++) {
        const subset: number[] = [];

        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                subset.push(nums[i]);
            }
        }

        result.push(subset);
    }

    return result;
}
```

**Example:**
```
nums = [a, b, c]  (n=3)

mask=0 (000): {}
mask=1 (001): {a}
mask=2 (010): {b}
mask=3 (011): {a, b}
mask=4 (100): {c}
mask=5 (101): {a, c}
mask=6 (110): {b, c}
mask=7 (111): {a, b, c}
```

